import com.crowdin.client.core.http.exceptions.HttpBadRequestException;
import com.crowdin.client.core.http.exceptions.HttpException;
import com.crowdin.client.projectsgroups.model.Project;
import com.crowdin.client.sourcefiles.model.FileInfo;
import com.crowdin.client.stringtranslations.model.LanguageTranslations;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class JacksonJsonTransformerTest {

    @Test
    public void parseHttpExceptionClassTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{\"message\":\"Error Message\",\"code\":404}";
        HttpException exception = transformer.parse(json, HttpException.class);
        assertNotNull(exception);
        assertEquals("Error Message", exception.getMessage());
        assertEquals(404, exception.getCode());
    }

    @Test
    public void parseHttpBadRequestExceptionClassTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{\"message\":\"Error Message\",\"code\":400}";
        HttpBadRequestException exception = transformer.parse(json, HttpBadRequestException.class);
        assertNotNull(exception);
        assertEquals("Error Message", exception.getMessage());
        assertEquals(400, exception.getCode());
    }

    @Test
    public void parseProjectClassTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{\"id\":1,\"name\":\"Test Project\"}";
        Project project = transformer.parse(json, Project.class);
        assertNotNull(project);
        assertEquals(1, project.getId().intValue());
        assertEquals("Test Project", project.getName());
    }

    @Test
    public void parseFileInfoClassTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{\"id\":1,\"name\":\"Test File\"}";
        FileInfo fileInfo = transformer.parse(json, FileInfo.class);
        assertNotNull(fileInfo);
        assertEquals(1, fileInfo.getId().intValue());
        assertEquals("Test File", fileInfo.getName());
    }

    @Test
    public void parseLanguageTranslationsClassTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{\"languageId\":1,\"translation\":\"Test Translation\"}";
        LanguageTranslations translations = transformer.parse(json, LanguageTranslations.class);
        assertNotNull(translations);
        assertEquals(1, translations.getLanguageId().intValue());
        assertEquals("Test Translation", translations.getTranslation());
    }

    @Test
    public void convertProjectClassTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        Project project = new Project();
        project.setId(1L);
        project.setName("Test Project");
        String json = transformer.convert(project);
        assertNotNull(json);
        assertEquals("{\"id\":1,\"name\":\"Test Project\"}", json);
    }

    @Test
    public void convertFileInfoClassTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        FileInfo fileInfo = new FileInfo();
        fileInfo.setId(1L);
        fileInfo.setName("Test File");
        String json = transformer.convert(fileInfo);
        assertNotNull(json);
        assertEquals("{\"id\":1,\"name\":\"Test File\"}", json);
    }

    @Test
    public void convertLanguageTranslationsClassTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        LanguageTranslations translations = new LanguageTranslations();
        translations.setLanguageId(1L);
        translations.setTranslation("Test Translation");
        String json = transformer.convert(translations);
        assertNotNull(json);
        assertEquals("{\"languageId\":1,\"translation\":\"Test Translation\"}", json);
    }
